CREATE TABLE incident_followups (record_id TEXT PRIMARY KEY REFERENCES records(id), condominium_id TEXT NOT NULL REFERENCES condominiums(id), payload TEXT NOT NULL CHECK(json_valid(payload)), version INTEGER NOT NULL DEFAULT 1, updated_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);
CREATE INDEX incident_event_date ON records(condominium_id,kind,json_extract(payload,'$.occurredAt'));
CREATE INDEX incident_parent ON records(condominium_id,json_extract(payload,'$.relatedIncidentId')) WHERE kind='incident';
CREATE TRIGGER incident_followup_created AFTER INSERT ON incident_followups BEGIN INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'accident_followup_created',NEW.record_id,NEW.version,NEW.updated_at); END;
CREATE TRIGGER incident_followup_updated AFTER UPDATE ON incident_followups BEGIN INSERT INTO item_revisions(resource_id,condominium_id,actor_id,version,snapshot,happened_at) VALUES(OLD.record_id,OLD.condominium_id,NEW.updated_by,OLD.version,OLD.payload,NEW.updated_at); INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'accident_followup_updated',NEW.record_id,NEW.version,NEW.updated_at); END;
